def proverb(*pieces, qualifier=None):
    lines = [
        f"For want of a {current} the {consequence} was lost."
        for current, consequence in zip(pieces, pieces[1:])
    ]
    if pieces:
        first = pieces[0]
        if qualifier:
            lines.append(f"And all for the want of a {qualifier} {first}.")
        else:
            lines.append(f"And all for the want of a {first}.")
    return lines
